# פרק 7 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=7
TITLE='מערכת בתי המשפט בישראל'
SUM=[' <p>מבנה הערכאות, מקורן ב<strong>חוק יסוד: השפיטה</strong> ובחוק בתי המשפט.</p> <h3>7.1 הערכאות הרגילות</h3> <p><strong>בית משפט השלום</strong> — הערכאה הנמוכה (רוב התיקים האזרחיים והפליליים); <strong>בית המשפט המחוזי</strong> — ערכאה ראשונה בעניינים כבדים וערכאת ערעור על השלום; <strong>בית המשפט העליון</strong> — הערכאה העליונה, ערעורים, ויושב גם כ<strong>בג"ץ</strong>.</p> <h3>7.2 בתי דין מיוחדים</h3> <p>לצד המערכת הרגילה: <strong>בתי הדין לעבודה</strong>, <strong>בתי הדין הדתיים</strong> (מעמד אישי), בתי דין צבאיים, ובתי משפט לעניינים מנהליים.</p> <h3>7.3 עקרונות</h3> <p><strong>פומביות הדיון</strong>, זכות ערעור, ומדרג ערכאות המאפשר ביקורת ותיקון טעויות.</p> <h3>7.4 נקודות מפתח למבחן</h3> <ul><li>שלום → מחוזי → עליון (+בג"ץ).</li><li>בתי דין מיוחדים: עבודה, דתיים, צבאיים, מנהליים.</li><li>פומביות + זכות ערעור.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('בג״ץ 8638/03 אמיר נ׳ בית הדין הרבני הגדול בירושלים', 'אחרי שהליך הגירושין הסתיים, נדון בבית הדין הרבני סכסוך רכושי בין בני הזוג לשעבר בטענה להפרת הסכם הגירושין. נשאלה השאלה מאין שואב בית הדין סמכות לדון בכך — מהחוק או מהסכמת הצדדים.', 'העתירה התקבלה. נקבע שהתערבות בג״ץ בהחלטות בתי דין דתיים מוגבלת למקרים קיצוניים — חריגה מסמכות, פגיעה בכללי הצדק הטבעי, סטייה מהוראות חוק המופנות לבית הדין או צורך בסעד מן הצדק. ההכרעה סימנה שבית הדין הרבני אינו מוסמך לשמש כבורר בסכסוך אזרחי — סמכותו נובעת מהחוק בלבד.'), ('בג״ץ 2232/03 פלונית נ׳ בית הדין הרבני האזורי תל אביב-יפו', 'יהודים אזרחי ישראל שנישאו בנישואין אזרחיים בקפריסין; כשהנישואין עלו על שרטון, בית הדין הרבני התיר את הקשר. האישה טענה שבית הדין פעל שלא כדין.', 'נקבע שלבתי הדין הרבניים סמכות ייחודית להתיר גם נישואין אזרחיים של יהודים שנערכו בחו״ל, וכי העילה המתאימה להתרתם היא עצם התמוטטות הנישואין — ולא בהכרח עילת גירושין דתית. פסק הדין ממחיש את היקף הסמכות הייחודית בענייני גירושין.'), ('בג״ץ 3914/92 לב נ׳ בית הדין הרבני האזורי בתל אביב-יפו', 'בית הדין הרבני הוציא, במסגרת הליך גירושין, צו עיכוב יציאה מהארץ נגד אישה שביקשה לנסוע לחופשה ולעסקים, בנימוק שהנסיעה תפגע בסיכויי השלום בית.', 'נקבע שלבתי הדין הדתיים, ככל ערכאה שיפוטית, יש סמכות טבועה לקבוע את סדרי הדין שלהם — אך זו סמכות שלטונית שיש להפעילה בסבירות ותוך איזון ראוי עם זכויות היסוד, כמו חופש התנועה. בית דין דתי אינו פועל בחלל ריק חוקתי.'), ('בג״ץ 4602/13 פלונית נ׳ בית הדין הרבני האזורי חיפה', 'עתירה נגד פסק דין של בית הדין הרבני הגדול שדחה טענת שיתוף ספציפי של אישה בבית המגורים, בטענה שבית הדין נתן משקל לבגידה נטענת ובכך החיל דין דתי בעניין רכושי.', 'בדעת רוב נדחתה העתירה (בדעת מיעוט סבר השופט עמית שיש להתערב). הפרשה ממחישה כי בג״ץ אינו ערכאת ערעור על בית הדין הרבני, ומתערב רק כשמוכחת חריגה מסמכות או פגיעה מהותית בעקרונות שהדין האזרחי מחייב.'), ('בג״ץ 5492/07 בוארון נ׳ בית הדין הארצי לעבודה', 'אלמנות שקצבאותיהן מהמוסד לביטוח לאומי הופסקו כי נקבע שהן חיות עם בן זוג חדש. בתי הדין האזוריים פסקו לטובתן, אך בית הדין הארצי הכריע נגדן — והן עתרו לבג״ץ.', 'העתירה נדחתה: בהחלטת בית הדין הארצי לא נפלה טעות משפטית מהותית המצדיקה התערבות. זה המבחן המרכזי — על בית הדין הארצי אין ערעור, ובג״ץ מתערב רק בטעות משפטית מהותית שהצדק מחייב לתקן.'), ('בג״ץ 1074/93 היועץ המשפטי לממשלה נ׳ בית הדין הארצי לעבודה', 'ההסתדרות הודיעה על שביתה בבזק בתגובה להחלטת הממשלה לפתוח את תחום הטלפוניה לתחרות. בית הדין האזורי אסר את השביתה, אך בית הדין הארצי ביטל את הצו.', 'בג״ץ קיבל את העתירה והתערב בפסק הדין של בית הדין הארצי: הוא סיווג שביתות לכלכליות, פוליטיות ו"מעין־פוליטיות", וקבע ששביתה מעין־פוליטית מצדיקה לכל היותר שביתת מחאה קצרה. פסק הדין מראה שהפיקוח של בג״ץ על בתי הדין לעבודה, אף שהוא מצומצם, אינו תיאורטי.')]
QS=[{'q': 'מהו החוק שקובע את העקרונות החוקתיים של מערכת השפיטה — עצמאות השופטים, מעמד בג״ץ וזכות הערעור?', 'o': ['תקנות סדר הדין האזרחי', 'חוק־יסוד: השפיטה', 'חוק בתי המשפט [נוסח משולב]', 'חוק־יסוד: הממשלה'], 'c': 1, 'e': 'נכון. חוק־יסוד: השפיטה (1984) קובע את העקרונות: סמכות שפיטה, אי־תלות, מינוי שופטים, בג״ץ, ערעור והלכה פסוקה.'}, {'q': 'מה קובע ס׳ 1(ג) לחוק־יסוד: השפיטה?', 'o': ['שהלכת העליון מחייבת את כל בתי המשפט', 'שלא יוקם בית משפט או בית דין למקרה מיוחד', 'שבית המשפט העליון יושב בירושלים', 'שכל פסק דין ניתן לערעור בזכות'], 'c': 1, 'e': 'נכון. ס׳ 1(ג) אוסר על הקמת ערכאה אד־הוק לתיק מסוים — ערובה לשוויון ולמניעת "תפירת" שופט.'}, {'q': 'נאשם הואשם בעבירה שהעונש המרבי עליה בחוק הוא 10 שנות מאסר, אך התביעה מעריכה שיקבל עונש של שנה. היכן יידון התיק (בהנחה שאין חריג מיוחד)?', 'o': ['לפי בחירת הנאשם', 'בבית משפט השלום, כי העונש הצפוי נמוך', 'בבית המשפט המחוזי, כי העונש המרבי בחוק עולה על 7 שנים', 'בבית המשפט העליון כערכאה ראשונה'], 'c': 2, 'e': 'נכון. שלום דן בעבירות שעונשן עד 7 שנים; עבירה שעונשה 10 שנים עוברת למחוזי לפי הסמכות השיורית, ואף נדונה בשלושה שופטים.'}, {'q': 'תובע הגיש לבית משפט השלום תביעה כספית על 2.4 מיליון ₪. עד מתן פסק הדין, בתוספת ריבית והצמדה, הגיע הסכום ל־2.7 מיליון ₪. מה הדין?', 'o': ['פסק הדין בטל', 'התיק חייב לעבור למחוזי', 'התובע חייב לוותר על הסכום העודף', 'בית משפט השלום נשאר מוסמך, כי הסכום נבחן ביום הגשת התביעה'], 'c': 3, 'e': 'נכון. ס׳ 51(א)(2) קובע שהסכום נבחן ביום הגשת התובענה, גם אם עלה אחר כך מחמת שערוך, הצמדה, ריבית והוצאות.'}, {'q': 'בעל דירה תובע לפנות שוכר מדירה ששוויה 4 מיליון ₪. לאיזה בית משפט תוגש התביעה?', 'o': ['לשלום, כי תביעות חזקה ושימוש במקרקעין בסמכותו בכל שווי', 'לבית המשפט לעניינים מינהליים', 'לבג״ץ', 'למחוזי, כי השווי עולה על 2.5 מיליון ₪'], 'c': 0, 'e': 'נכון. לפי ס׳ 51(א)(3) תביעות חזקה ושימוש במקרקעין נדונות בשלום "יהיה שוויו של נושא התביעה אשר יהיה".'}, {'q': 'שני אחים מתדיינים על הבעלות במגרש ששוויו 900,000 ₪. היכן תוגש התביעה?', 'o': ['בבית המשפט לתביעות קטנות', 'בבית המשפט המחוזי, כי תביעת בעלות במקרקעין אינה בסמכות השלום', 'בבית הדין הרבני', 'בבית משפט השלום, כי הסכום נמוך מ־2.5 מיליון ₪'], 'c': 1, 'e': 'נכון. ס׳ 51(א)(3) מוציא במפורש תביעות אחרות הנוגעות למקרקעין (כמו בעלות) מסמכות השלום, ולכן הן במחוזי לפי הסמכות השיורית.'}, {'q': 'מה מאפיין את סמכותו של בג״ץ לפי ס׳ 15(ג) לחוק־יסוד: השפיטה?', 'o': ['היא חלה רק על החלטות הכנסת', 'היא מוגבלת לענייני ביטחון', 'היא סמכות שיורית ושבשיקול דעת — בעניינים שאינם בסמכות ערכאה אחרת ושבהם יש צורך בסעד למען הצדק', 'היא סמכות ערעור על כל ערכאה'], 'c': 2, 'e': 'נכון. "בענינים אשר הוא רואה צורך לתת בהם סעד למען הצדק ואשר אינם בסמכותו של בית משפט או של בית דין אחר" — שיורית ושבשיקול דעת.'}, {'q': 'עובד הפסיד בבית הדין האזורי לעבודה ובערעור בבית הדין הארצי. מה הצעד הבא האפשרי?', 'o': ['בקשת רשות ערעור לבית המשפט המחוזי', 'ערעור בזכות לבית המשפט העליון', 'עתירה לבג״ץ, שיתערב רק בטעות משפטית מהותית שהצדק מחייב לתקן', 'דיון נוסף בבית הדין האזורי'], 'c': 2, 'e': 'נכון. הדרך היחידה היא עתירה לבג״ץ, והוא מתערב במשורה — כפי שנקבע למשל בבג״ץ 5492/07.'}, {'q': 'מי יושב בבתי הדין לעבודה לצד השופטים המקצועיים?', 'o': ['נציגי ציבור מטעם העובדים ומטעם המעסיקים', 'מושבעים', 'נציגי לשכת עורכי הדין', 'רבנים'], 'c': 0, 'e': 'נכון. נציגי ציבור משני צדי יחסי העבודה יושבים בהרכבים כדי להביא לדיון היכרות מעשית עם עולם העבודה.'}, {'q': 'בני זוג יהודים, אזרחי ישראל, מבקשים להתגרש. היכן יינתן פסק הגירושין עצמו?', 'o': ['לפי הסכמת בני הזוג — בכל ערכאה', 'בבית המשפט המחוזי', 'בבית המשפט לענייני משפחה', 'בבית הדין הרבני, שלו סמכות ייחודית בנישואין וגירושין של יהודים'], 'c': 3, 'e': 'נכון. לפי חוק שיפוט בתי דין רבניים (נישואין וגירושין), התשי״ג–1953, הסמכות בגירושין של יהודים בישראל ייחודית לבית הדין הרבני.'}, {'q': 'אישה התדיינה בבית הדין הרבני בעניין רכוש במשך חודשים בלי להתנגד לסמכותו. לאחר שהפסידה עתרה לבג״ץ בטענה שבית הדין לא היה מוסמך. מה הקושי העיקרי בעתירתה?', 'o': ['היא הייתה צריכה לערער לבית המשפט המחוזי', 'פסקי דין של בתי דין דתיים אינם מחייבים', 'בג״ץ לעולם אינו דן בעתירות נגד בתי דין דתיים', 'לפי ס׳ 15(ד)(4) בג״ץ לא ייזקק לטענה אם לא הועלתה שאלת הסמכות בהזדמנות הראשונה'], 'c': 3, 'e': 'נכון. הסעיף מתנה את הדיון בכך שהמבקש עורר את שאלת הסמכות בהזדמנות הראשונה שהייתה לו.'}, {'q': 'מה ההבדל המשמעותי בין עתירה לבג״ץ לבין עתירה לבית המשפט לעניינים מינהליים?', 'o': ['בית המשפט לעניינים מינהליים דן בכל עתירה נגד המדינה', 'אין הבדל, אלו שמות שונים לאותה ערכאה', 'על פסק דין של בית המשפט לעניינים מינהליים ניתן לערער לעליון, ואילו על פסק דין של בג״ץ אין ערעור', 'בג״ץ דן רק בעתירות של תאגידים'], 'c': 2, 'e': 'נכון. זה אחד מטעמי החוק משנת 2000: להוריד עומס מבג״ץ ולאפשר ערכאת ערעור.'}, {'q': 'כמה חברים בוועדה לבחירת שופטים לפי ס׳ 4(ב) לחוק־יסוד: השפיטה (הנוסח שבתוקף עד הכנסת ה־26)?', 'o': ['9', '7', '11', '15'], 'c': 0, 'e': 'נכון. 9 חברים: נשיא העליון ושני שופטי עליון, שר המשפטים ושר נוסף, שני ח״כים ושני נציגי לשכת עורכי הדין.'}, {'q': 'מה הרוב הנדרש כיום (לפני כניסת תיקון 2025 לתוקף) לבחירת שופט לבית המשפט העליון?', 'o': ['רוב רגיל של המשתתפים בהצבעה', 'פה אחד', '5 חברים ובהם נציג קואליציה ונציג אופוזיציה', '7 מתוך 9 חברי הוועדה'], 'c': 3, 'e': 'נכון. ס׳ 7(ג)(2) לחוק בתי המשפט דורש 7 מ־9 (ואם משתתפים פחות — רוב שאינו נמוך ממספר המשתתפים פחות שניים).'}, {'q': 'מה מהבאים נכון לגבי התיקון לחוק־יסוד: השפיטה משנת 2025 בעניין הוועדה לבחירת שופטים?', 'o': ['נציגי לשכת עורכי הדין מוחלפים בשני נציגי ציבור שבוחרים חברי הכנסת — אחד בידי הקואליציה ואחד בידי האופוזיציה', 'הוא חל מיד עם פרסומו', 'הוא ביטל את חברות שופטי העליון בוועדה', 'הוא הגדיל את הוועדה ל־11 חברים'], 'c': 0, 'e': 'נכון. לפי לשון התיקון, במקום שני נציגי הלשכה ייבחרו שני נציגי ציבור בכנסת — אחד בידי הקואליציה ואחד בידי האופוזיציה.'}, {'q': 'מהי "סמכות נגררת" לפי ס׳ 76 לחוק בתי המשפט?', 'o': ['סמכות ערעור של המחוזי על השלום', 'סמכות לדון בכל עניין שהצדדים הסכימו עליו', 'סמכות להעביר תיק למחוז אחר', 'סמכות להכריע בשאלה אגבית שבסמכות ערכאה אחרת, לצורך אותו עניין בלבד'], 'c': 3, 'e': 'נכון. כשמתעוררת "דרך אגב" שאלה שהכרעתה דרושה, ביהמ״ש רשאי להכריע בה לצורך העניין שלפניו — גם אם היא בסמכות ייחודית של ערכאה אחרת.'}, {'q': 'חוזה בין חברה מתל אביב לספק מאילת קובע שכל סכסוך יידון "בבית המשפט המחוזי בתל אביב". הסכסוך הוא על 300,000 ₪. מה הדין?', 'o': ['התניה יכולה לקבוע את המקום (תל אביב), אך לא להקנות סמכות עניינית למחוזי — התביעה תוגש לשלום בתל אביב', 'התניה בטלה כולה, והתביעה תוגש באילת', 'הסכסוך יידון בבג״ץ', 'התניה תקפה במלואה, והתיק יידון במחוזי בתל אביב'], 'c': 0, 'e': 'נכון. תניית שיפוט מכריעה בסמכות המקומית (תקנה 7(א)), אך סמכות עניינית נקבעת בחוק ואינה ניתנת להסכמה; 300,000 ₪ הם בסמכות השלום.'}, {'q': 'בעל דין שהפסיד במחוזי בערעור על פסק דין של השלום, רוצה לפנות לעליון. מה מצבו?', 'o': ['עליו לבקש רשות ערעור ("גלגול שלישי"), שניתנת במשורה בשאלה בעלת חשיבות כללית או לשם מניעת עיוות דין', 'יש לו ערעור בזכות', 'עליו לבקש דיון נוסף', 'אין לו שום דרך, גם לא ברשות'], 'c': 0, 'e': 'נכון. ס׳ 41(ב) מתיר ערעור על פסק דין של המחוזי בערעור רק ברשות, והפסיקה מצמצמת את מתן הרשות.'}, {'q': 'מה נקבע בבג״ץ 2232/03 בעניין נישואין אזרחיים של יהודים שנערכו בקפריסין?', 'o': ['שהנישואין אינם מוכרים בכל צורה, ולכן אין צורך להתירם', 'שבית הדין הרבני מוסמך להתירם, והעילה המתאימה היא התמוטטות הנישואין', 'שרק בית המשפט לענייני משפחה מוסמך להתירם', 'שבני הזוג חייבים להתגרש בקפריסין'], 'c': 1, 'e': 'נכון. בית הדין הרבני מוסמך באופן ייחודי להתיר נישואין אזרחיים של יהודים, והעילה היא עצם התמוטטות הקשר — לא בהכרח עילה דתית.'}, {'q': 'מה מבטא ס׳ 2 לחוק־יסוד: השפיטה?', 'o': ['ששר המשפטים רשאי להנחות שופטים בעניינים עקרוניים', 'שהכנסת רשאית לבטל פסקי דין', 'שבענייני שפיטה אין מרות על השופט זולת מרותו של הדין', 'שהשופטים כפופים לנשיא בית המשפט העליון בהכרעותיהם'], 'c': 2, 'e': 'נכון. זהו עקרון אי־התלות: "בענייני שפיטה אין מרות על מי שבידו סמכות שפיטה, זולת מרותו של הדין".'}, {'q': 'בג״ץ התבקש להתערב בפסק דין של בית הדין הרבני הגדול בעניין רכושי. מה הגישה הכללית שנקבעה בפסיקה (למשל בבג״ץ 8638/03)?', 'o': ['בג״ץ בוחן מחדש את כל העובדות כמו ערכאת ערעור', 'בג״ץ אינו מתערב לעולם', 'בג״ץ מעביר את התיק למחוזי', 'בג״ץ מתערב רק במקרים חריגים — חריגה מסמכות, פגיעה בכללי הצדק הטבעי, סטייה מהוראות חוק המופנות לבית הדין או צורך בסעד מן הצדק'], 'c': 3, 'e': 'נכון. כך נקבע בבג״ץ 8638/03: ההתערבות מוגבלת למקרים קיצוניים שנמנו.'}, {'q': 'מהו הכלל לגבי פסק דין של בג״ץ?', 'o': ['ניתן לערער עליו לכנסת', 'אין ערעור עליו; ניתן לבקש דיון נוסף בעילות הקבועות בחוק', 'ניתן לערער עליו לבית המשפט החוקתי', 'ניתן לערער עליו לבית המשפט העליון בהרכב של חמישה'], 'c': 1, 'e': 'נכון. ס׳ 17 לחוק היסוד מוציא את פסקי הדין של העליון מזכות הערעור, וס׳ 18 מאפשר דיון נוסף בעילות שבחוק.'}]
MAR=[]
